def validate_gdpr_consent_record(consent_record):
    errors = {}

    # Check for 'consented' field
    if 'consented' not in consent_record or consent_record['consented'] is not True:
        errors['consented'] = "The 'consented' field is missing or not set to True."

    # Check for 'purpose' field
    if 'purpose' not in consent_record or not consent_record['purpose']:
        errors['purpose'] = "The 'purpose' field is missing or empty."

    # Check for 'timestamp' field
    if 'timestamp' not in consent_record:
        errors['timestamp'] = "The 'timestamp' field is missing."

    # Check if 'timestamp' is a valid UTC ISO-8601 string
    try:
        datetime.fromisoformat(consent_record['timestamp'])
    except ValueError:
        errors['timestamp'] = "The 'timestamp' field is not a valid UTC ISO-8601 string."

    # Check for 'withdrawal_url' field
    if 'withdrawal_url' not in consent_record:
        errors['withdrawal_url'] = "The 'withdrawal_url' field is missing."
    elif not consent_record['withdrawal_url']:
        errors['withdrawal_url'] = "The 'withdrawal_url' field is empty."

    return errors

